create table if not exists public.book_reel_watch_events (id uuid primary key default gen_random_uuid(),reel_id uuid not null references public.book_reels(id) on delete cascade,viewer_id uuid null references auth.users(id) on delete set null,watched_seconds integer not null default 0 check(watched_seconds>=0 and watched_seconds<=86400),completed boolean not null default false,created_at timestamptz not null default now());create index if not exists book_reel_watch_events_reel_idx on public.book_reel_watch_events(reel_id,created_at desc);alter table public.book_reel_watch_events enable row level security;drop policy if exists "Anyone can record reel watch events" on public.book_reel_watch_events;create policy "Anyone can record reel watch events" on public.book_reel_watch_events for insert to anon,authenticated with check(viewer_id is null or viewer_id=auth.uid());revoke all on public.book_reel_watch_events from anon,authenticated;grant insert on public.book_reel_watch_events to anon,authenticated;
create or replace function public.get_my_book_reel_analytics() returns table(reel_id uuid,book_title text,created_at timestamptz,view_count bigint,unique_viewers bigint,reaction_count bigint,comment_count bigint,total_watch_seconds bigint,completed_plays bigint) language sql stable security definer set search_path=public as $$ select r.id,coalesce(r.book_title,'Reader moment'),r.created_at,(select count(*) from public.book_reel_views v where v.reel_id=r.id),(select count(distinct v.viewer_id) from public.book_reel_views v where v.reel_id=r.id and v.viewer_id is not null),(select count(*) from public.book_reel_reactions x where x.reel_id=r.id),(select count(*) from public.book_reel_comments c where c.reel_id=r.id),(select coalesce(sum(w.watched_seconds),0) from public.book_reel_watch_events w where w.reel_id=r.id),(select count(*) from public.book_reel_watch_events w where w.reel_id=r.id and w.completed) from public.book_reels r where r.user_id=auth.uid() order by r.created_at desc;$$;revoke all on function public.get_my_book_reel_analytics() from public;grant execute on function public.get_my_book_reel_analytics() to authenticated;